function Header({user,onProfile}){return <View style={s.header}><Brand/><Pressable onPress={onProfile} style={s.headerAvatar} accessibilityRole="button" accessibilityLabel="Open profile"><Text style={s.headerAvatarText}>{user.fullName?.[0]||'O'}</Text></Pressable></View>}
function Home({session,setScreen,startNew}){const hour=new Date().getHours(),greeting=hour<12?'Good Morning':hour<18?'Good Afternoon':'Good Evening',officer=session.user.fullName||'Officer';return <ScrollView style={s.screenScroll} contentContainerStyle={s.homeScroll}><Text style={s.homeEyebrow}>FIELD COMPANION</Text><Text style={s.homeGreeting}>{greeting},{`\n`}{officer}</Text><Text style={s.homeSupport}>Field companion for presumptive field-test documentation.</Text><Pressable style={s.homePrimaryCard} onPress={startNew}><View pointerEvents="none" style={s.homePrimaryAccent}/><View style={s.homePrimaryCopy}><Text style={s.homePrimaryKicker}>NEW FIELD TEST</Text><Text style={s.homePrimaryTitle}>Start a new field test</Text><Text style={s.homePrimaryText}>Capture evidence and create a secure record.</Text></View><View style={s.homePrimaryVisual}><View style={s.homeFlaskBubble}><Text style={s.homeFlask}>⚗</Text></View><Text style={s.homeArrow}>›</Text></View></Pressable><Pressable style={s.homeSecondaryCard} onPress={()=>setScreen('history')}><View style={s.homeCardIcon}><Text style={s.homeCardIconText}>◫</Text></View><View style={s.homeCardCopy}><Text style={s.homeCardKicker}>TEST HISTORY</Text><Text style={s.homeCardTitle}>View past field tests and results.</Text></View><Text style={s.homeCardArrow}>›</Text></Pressable><Pressable style={s.homeSecondaryCard} onPress={()=>setScreen('profile')}><View style={s.homeCardIcon}><Text style={s.homeCardIconText}>◉</Text></View><View style={s.homeCardCopy}><Text style={s.homeCardKicker}>PROFILE</Text><Text style={s.homeCardTitle}>Account and session details.</Text></View><Text style={s.homeCardArrow}>›</Text></Pressable><View style={s.homeNotice}><Text style={s.homeNoticeTitle}>PRESUMPTIVE RESULTS ONLY</Text><Text style={s.homeNoticeText}>Chromora does not replace laboratory confirmatory testing.</Text></View></ScrollView>}
function BottomNav({screen,setScreen,onProfileNav}){const items=[['home','⌂','HOME'],['history','◫','TESTS'],['profile','◉','PROFILE']];return <View style={s.bottomNav}>{items.map(([target,icon,label])=><Pressable key={target} style={s.bottomNavItem} onPress={()=>target==='profile'?onProfileNav():setScreen(target)}><Text style={[s.bottomNavIcon,screen===target&&s.bottomNavActive]}>{icon}</Text><Text style={[s.bottomNavLabel,screen===target&&s.bottomNavActive]}>{label}</Text>{screen===target&&<View style={s.bottomNavIndicator}/>}</Pressable>)}</View>}
function NewTest({setScreen,draft,setDraft,requestDiscard}){const [locationState,setLocationState]=useState(draft.location?'CAPTURED':'NOT CAPTURED');const chooseImage=async source=>{const permission=source==='camera'?await ImagePicker.requestCameraPermissionsAsync():await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted)return;const result=source==='camera'?await ImagePicker.launchCameraAsync({mediaTypes:['images'],quality:.8}):await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],quality:.8});if(!result.canceled)setDraft({...draft,asset:result.assets[0],capturedAt:new Date().toISOString()})};const captureLocation=async()=>{setLocationState('REQUESTING');const permission=await Location.requestForegroundPermissionsAsync();if(permission.status!=='granted'){setLocationState('PERMISSION NOT GRANTED');return}try{const position=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.Balanced});setDraft({...draft,location:{latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy}});setLocationState('CAPTURED')}catch{setLocationState('UNAVAILABLE')}};const quality=draft.asset?(draft.asset.width>=800&&draft.asset.height>=600?'ACCEPTABLE':'REVIEW RECOMMENDED'):null;const profileLabel=draft.profile==='General colourimetric field test'?'Prototype Colorimetric Profile A':draft.profile;return <ScrollView style={s.screenScroll} contentContainerStyle={s.captureScroll}><View style={s.captureHeader}><Pressable onPress={requestDiscard}><Text style={s.captureBack}>← BACK</Text></Pressable><View><Text style={s.captureHeaderTitle}>New Field Test</Text><Text style={s.captureStep}>STEP 1 OF 3</Text></View></View><View style={s.captureProfileCard}><Text style={s.captureLabel}>TEST PROFILE</Text><Text style={s.captureProfileName}>{profileLabel}</Text></View><View style={s.captureCameraCard}><View style={s.captureFrame}>{draft.asset?<Image source={{uri:draft.asset.uri}} style={s.capturePreview}/>:<><View style={s.captureCornerTopLeft}/><View style={s.captureCornerBottomRight}/><View style={s.captureTarget}><Text style={s.captureTargetDot}>+</Text></View><Text style={s.captureFrameCopy}>Place test area and reference colour card{`\n`}inside the frame</Text></>}</View><View style={s.captureButtonRow}><Button label="CAPTURE PHOTO" onPress={()=>chooseImage('camera')} style={s.capturePhotoButton}/><Button outline label="UPLOAD FROM GALLERY" onPress={()=>chooseImage('gallery')} style={s.captureGalleryButton}/></View></View><View style={s.captureInfoRow}><Text style={s.captureInfoIcon}>i</Text><View><Text style={s.captureInfoTitle}>REFERENCE COLOUR CARD</Text><Text style={s.captureInfoText}>Not implemented in the current prototype.</Text></View></View><View style={s.captureGpsCard}><View><Text style={s.captureLabel}>LOCATION</Text><Text style={locationState==='CAPTURED'?s.captureGpsValue:s.captureGpsPending}>{draft.location?`${Number(draft.location.latitude).toFixed(5)}, ${Number(draft.location.longitude).toFixed(5)} | Accuracy +/-${Math.round(draft.location.accuracy||0)} m`:locationState}</Text></View><Pressable onPress={captureLocation} style={s.captureRefresh}><Text style={s.captureRefreshText}>REFRESH</Text></Pressable></View>{quality&&<View style={s.captureQualityCard}><Text style={s.captureLabel}>CAPTURE QUALITY</Text><Text style={quality==='ACCEPTABLE'?s.captureQualityGood:s.captureQualityReview}>{quality}</Text></View>}<Button label="CONTINUE TO REVIEW" onPress={()=>setScreen('preview')} disabled={!draft.asset} style={s.captureContinueButton}/></ScrollView>}
function Preview({setScreen,draft,setDraft,session,requestDiscard}){const initialQuality=draft.asset?.width>=800&&draft.asset?.height>=600?'ACCEPTABLE':'REVIEW RECOMMENDED';const [quality,setQuality]=useState(initialQuality),[busy,setBusy]=useState(false),[error,setError]=useState(''),[connection,setConnection]=useState(null);const retake=()=>{setDraft({...draft,asset:null,capturedAt:null});setScreen('new')};const continueFlow=async()=>{setBusy(true);setError('');setConnection(null);const health=await checkBackendHealth();if(__DEV__)console.info(`[Chromora mobile] Continue to Analysis API URL: ${health.apiUrl||'unresolved'}`);if(!health.available){setConnection(health);setBusy(false);return}try{let record=draft.pendingRecord;if(!record){const created=await request('/test-records',{token:session.token,method:'POST',body:{testProfile:draft.profile,capturedAt:draft.capturedAt||new Date().toISOString(),latitude:draft.location?.latitude??null,longitude:draft.location?.longitude??null,locationAccuracy:draft.location?.accuracy??null,draft:true}});record=created.record;setDraft(current=>({...current,pendingRecord:record}))}const form=new FormData(),file=await evidenceFile(draft.asset);form.append('image',file);const uploaded=await request(`/test-records/${record.id}/evidence`,{token:session.token,method:'POST',form});setQuality(uploaded.imageQuality?.state||initialQuality);setDraft(current=>({...current,record:uploaded.record,pendingRecord:uploaded.record}));setScreen('analysis')}catch(e){setError(e.message)}finally{setBusy(false)}};const capturedAt=draft.capturedAt?new Date(draft.capturedAt).toLocaleString():'Not recorded';const details=[['LOCATION',draft.location?`${Number(draft.location.latitude).toFixed(5)}, ${Number(draft.location.longitude).toFixed(5)}`:'Not captured'],['GPS ACCURACY',draft.location?`+/-${Math.round(draft.location.accuracy||0)} m`:'Not captured'],['CAPTURE QUALITY',quality==='ACCEPTABLE'?'Acceptable':'Review Recommended'],['REFERENCE CARD','Not implemented'],['CAPTURED AT',capturedAt]];const ready=quality==='ACCEPTABLE';return <ScrollView style={s.screenScroll} contentContainerStyle={s.reviewScroll}><View style={s.reviewHeader}><Pressable onPress={requestDiscard}><Text style={s.captureBack}>← BACK</Text></Pressable><View><Text style={s.captureHeaderTitle}>Review Evidence</Text><Text style={s.captureStep}>STEP 2 OF 3</Text></View></View><View style={s.reviewPreviewCard}><Image source={{uri:draft.asset.uri}} style={s.reviewPreview}/><Pressable onPress={retake} style={s.reviewRetakePhoto}><Text style={s.reviewRetakePhotoText}>RETAKE PHOTO</Text></Pressable></View><View style={s.reviewDetailsCard}><Text style={s.reviewSectionTitle}>CAPTURE DETAILS</Text>{details.map(([label,value])=><View key={label} style={s.reviewDetailRow}><Text style={s.reviewDetailLabel}>{label}</Text><Text style={s.reviewDetailValue}>{value}</Text></View>)}</View><View style={ready?s.reviewReadyCard:s.reviewWarningCard}><Text style={ready?s.reviewReadyTitle:s.reviewWarningTitle}>{ready?'READY FOR ANALYSIS':'CAPTURE REVIEW RECOMMENDED'}</Text><Text style={ready?s.reviewReadyText:s.reviewWarningText}>{ready?'Basic image dimensions are acceptable for the current prototype workflow.':'Image dimensions are below the basic acceptable threshold. Retake if the test area or reference card is unclear.'}</Text></View><View style={s.reviewSafety}><Text style={s.reviewSafetyText}>Presumptive field-test workflow only. Laboratory confirmation is required for definitive identification.</Text></View>{connection?<BackendUnavailable connection={connection}/>:null}{error?<Text style={s.error}>{error}</Text>:null}<View style={s.reviewActions}><Button outline label="RETAKE" onPress={retake} style={s.reviewRetakeButton}/><Button label={busy?'STORING EVIDENCE...':'CONTINUE TO ANALYSIS'} onPress={continueFlow} disabled={!draft.asset||busy} style={s.reviewContinueButton}/></View></ScrollView>}
